import{_ as i,l as r,o as e,c as l,v as t,p as s,x as n,d as E,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"一致预期与分析师","description":"","frontmatter":{"title":"一致预期与分析师","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/analyst-consensus.md","filePath":"quant/analyst-consensus.md","lastUpdated":1789023840000}'),h={name:"quant/analyst-consensus.md"};function p(u,a,m,B,S,A){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="一致预期与分析师" tabindex="-1">一致预期与分析师 <a class="header-anchor" href="#一致预期与分析师" aria-label="Permalink to &quot;一致预期与分析师&quot;">​</a></h1><div class="epigraph"><p>一致预期是当时市场上可观察的盈利路径，不是 Compustat 的最终真实。未预期盈利的分母若用错「实际」或用错可知日，SUE 就变成前视会计。</p><footer>—— Diether, Malloy and Scherbina, Differences of Opinion and the Cross Section of Stock Returns, Journal of Finance, 2002；对照 IBES 用户指南对统计期与实际值的说明；Stickel, Womack 等对分析师修订的经典结果</footer></div><p><a href="/quant/fundamentals-restatements">上一课</a>把公司自己的数字做成 vintage。<a href="/quant/crsp-compustat">对齐课</a>把主键接好。本课的缺口是<strong>分析师信息集</strong>：IBES 一类共识、修订、离散度与「实际值」字段。Diether、Malloy 与 Scherbina（2002）表明预测离散度与收益相关，且数据构造（是否含停止覆盖等）会改变结论。后课指数成分换对象；本课不把共识写成「聪明的 Compustat」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SUE 常写成 \\((E-\\hat E)/\\sigma\\)。\\(\\hat E\\) 必须是公告前最后可知的共识，\\(\\sigma\\) 必须用当时可知的预测或历史意外。\\(E\\) 若取 Compustat 最终盈利，而 \\(\\hat E\\) 取 IBES，口径差（一次性项目、摊薄）会进入「意外」。IBES 自己的 actual 与共识同口径，通常更合适——但仍有发布时点。问题是每条预测的 <code>announce_ts</code> 与统计期：月度共识快照是哪一天的截面，能否在开盘前使用。</p><p>覆盖缺失不是随机：小盘、亏损、即将退市更少分析师。用共识特征做截面，等于在有覆盖的子宇宙上交易。离散度在覆盖为 1 时无定义。Diether 等强调对 IBES 文件版本与调整的处理；复制必须声明文件（Summary vs Detail）与复权调整。</p><h3 id="修订路径比静态共识更接近信息流" tabindex="-1">修订路径比静态共识更接近信息流 <a class="header-anchor" href="#修订路径比静态共识更接近信息流" aria-label="Permalink to &quot;修订路径比静态共识更接近信息流&quot;">​</a></h3><p>水平共识是存量；上调下调是流量。Stickel、Womack 一类结果表明修订带有收益效应，但也有缓慢扩散与可交易性限制。回测修订必须用修订公告时点，不能用月末快照里已经改完的数字去填月中交易。这与会计 vintage 同一纪律。</p><p><span class="marginnote">A 股一致预期来自 Wind、朝阳永续等。字段与调整（是否含预测机构当天）各异。原则：公告时点、口径一致、覆盖偏差。不要直接套 IBES 的美国财政日历。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>点-in-time：Detail 文件保留每条预测的有效区间，Summary 快照只在快照日使用。实际值用与共识同口径的字段，公告日用盈利公告时间戳（注意盘前盘后）。复权：预测与实际必须在同一股本基础上；拆股调整错误会造成假意外。离散度：至少两名分析师，声明是标准差还是变异系数，以及是否剔除过期预测。</p><p>与 CRSP 收益对齐时，事件窗从公告时点起，不是从财季末。盘后公告对当日收益的归属要明确：计入次日开盘。这与<a href="/quant/cn-limit-auction">集合竞价</a>在 A 股的开盘跳价是同一类时钟问题。</p><h3 id="停止覆盖与选择" tabindex="-1">停止覆盖与选择 <a class="header-anchor" href="#停止覆盖与选择" aria-label="Permalink to &quot;停止覆盖与选择&quot;">​</a></h3><p>分析师停止覆盖往往在坏消息附近。把停止当缺失、用旧共识填，会让困境公司看起来「仍有温和预期」。应把覆盖状态当特征或把停止当事件，而不是前向填充预测。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>共识是公开信息的压缩。有效市场下，水平共识已在价格里，可交易的是意外与修订。离散度代理意见分歧，在卖空约束下与高估相关（Miller；Diether 等）。这把本课接到<a href="/quant/securities-lending">借券</a>：高离散且难借的名字，空头腿可能实现不了。纸面的离散度溢价必须扣借券与覆盖偏差。</p><p>供应商的「一致预期」是加权与清洗后的产品。换供应商等于换过滤器，因子不可在未声明的情况下横比。后课数据商对照会把这写成一般原则。</p>',17)),(e(),s(d,null,{default:n(()=>[c(o,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20Det%5B%22%E9%80%90%E6%9D%A1%E9%A2%84%E6%B5%8B%20%2B%20%E6%97%B6%E7%82%B9%22%5D%20--%3E%20Snap%5B%22as-of%20%E5%85%B1%E8%AF%86%22%5D%0A%20%20Snap%20--%3E%20SUE%5B%22%E6%84%8F%E5%A4%96%20%E5%90%8C%E5%8F%A3%E5%BE%84%E5%AE%9E%E9%99%85%E5%80%BC%22%5D%0A%20%20Rev%5B%22%E4%BF%AE%E8%AE%A2%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20Flow%5B%22%E6%B5%81%E9%87%8F%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20Cov%5B%22%E8%A6%86%E7%9B%96%E4%B8%8E%E5%81%9C%E6%AD%A2%22%5D%20--%3E%20Sel%5B%22%E6%A0%B7%E6%9C%AC%E9%80%89%E6%8B%A9%22%5D%0A%20%20SUE%20--%3E%20Ret%5B%22%E5%85%AC%E5%91%8A%E5%90%8E%E6%94%B6%E7%9B%8A%22%5D%0A%20%20Flow%20--%3E%20Ret%0A%20%20Sel%20--%3E%20Ret%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供利用非公开分析师沟通或抢embargo 的方法。投资银行内部模型不在 IBES 宇宙。量化若把 NLP 纪要当「分析师」，那是另一数据源，时钟与许可另算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共识必须点-in-time；实际值与预测同口径，勿用 Compustat 最终盈利冒充。</li><li>修订是流量；停止覆盖是选择，不能前向填充。</li><li>离散度效应与卖空约束纠缠，须报告可实现版本。</li><li>出处：Diether, Malloy and Scherbina, <em>JF</em>, 2002；IBES 文档；Stickel / Womack 修订文献。</li></ul>',4))])}const q=i(h,[["render",p]]);export{f as __pageData,q as default};
